import {NRF52_BOARDS} from './nrf52-boards.js';
export function nrfBoardOverlay(c,scale){const b=NRF52_BOARDS[c.params.model];if(!b)return'';const xiao=b.id.startsWith('xiao'),p=b.pins.find(p=>p.id==='RESET'),x=xiao?12.5:p.x,y=xiao?13.5:p.y;const labels=b.pins.filter(p=>p.connectable!==false).map(p=>{const left=p.side==='left',bottom=p.side==='bottom',px=bottom?p.x+2:left?p.x-7:p.x+7,py=bottom?b.height+10:p.y+2;return `<text x="${px}" y="${py}" ${bottom?`transform="rotate(55 ${px} ${py})"`:''} text-anchor="${left?'end':'start'}" font-family="Consolas,monospace" font-size="6.4" font-weight="600" fill="#f4f2dc" stroke="#14212b" stroke-width="1.8" paint-order="stroke" pointer-events="none">${p.name.replace('BAT+ / RAW','BAT+').replace(/^GND\.\d+$/,'GND')}</text>`;}).join('');return `<g data-tiva-board="${c.id}" transform="scale(${scale})"><g data-tiva-control="RESET" role="button" tabindex="0" aria-label="${b.name} · ${xiao?'Reset butonu':'sanal reset, RST-GND'}" style="cursor:pointer"><title>${xiao?'Reset: firmware’i baştan başlat':'Sanal reset · gerçek kartta RST ile GND kısa devre edilir'}</title><circle cx="${x}" cy="${y}" r="${xiao?5:4.2}" fill="transparent" stroke="transparent" class="nrf-reset-hit"/></g>${labels}</g>`;}
